"""Generate query examples, report, viva and presentation outline from project facts."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
DOC=ROOT/'docs'
prefix='PREFIX k: <https://sumo-kars.local/traffic#>\n'
queries={
'speed_limit':'SELECT ?limit WHERE { k:ego k:speed_limit ?limit . }',
'current_lane':'SELECT ?lane WHERE { k:ego k:locatedAt ?lane . }',
'nearby_vehicles':'SELECT ?vehicle ?x ?v WHERE { k:ego k:x ?ex . ?vehicle a k:Vehicle; k:x ?x; k:hasSpeed ?v . FILTER (?vehicle != k:ego && ABS(?x-?ex)<100) }',
'traffic_light':'SELECT ?signal ?color WHERE { k:ego k:traffic_light ?signal; k:traffic_light_state ?color . }',
'upcoming_obstacle':'SELECT ?source ?start ?end WHERE { k:ego k:x ?x . ?c a k:Constraint; k:kind ?kind; k:source ?source; k:start ?start; k:end ?end . FILTER (?start > ?x && (?kind="spatial" || ?kind="spatial_temporal")) }',
'pedestrian_crossing':'SELECT ?start ?end ?speed WHERE { ?c k:source "crossing advisory"; k:start ?start; k:end ?end; k:speed ?speed . }',
'road_block':'SELECT ?source ?lane ?start ?end WHERE { ?c k:kind ?kind; k:source ?source; k:lane ?lane; k:start ?start; k:end ?end . FILTER (?kind="spatial" || ?kind="spatial_temporal") }',
'allowed_speed':'SELECT (MIN(?cap) AS ?allowed) WHERE { k:ego k:x ?x . ?c k:kind "spatial_speed"; k:start ?s; k:end ?e; k:speed ?cap . FILTER (?x>=?s && ?x<=?e) }',
'temporal_restriction':'SELECT ?source ?begin ?finish WHERE { ?c k:kind ?kind; k:source ?source; k:begin ?begin; k:finish ?finish . FILTER (?kind="spatial_temporal" || ?kind="spatial_temporal_speed") }',
'spatial_restriction':'SELECT ?source ?start ?end ?lane WHERE { ?c a k:Constraint; k:source ?source; k:start ?start; k:end ?end; k:lane ?lane . }'
}
for name,body in queries.items():
    (ROOT/'knowledge_graph/queries'/f'{name}.rq').write_text(prefix+body+'\n')
(DOC/'QUERIES.md').write_text('# SPARQL examples\n\nPlanner executes `constraints.rq` each planning cycle. The other ten files illustrate individual queries against the saved dynamic.ttl. Nearby vehicles uses longitudinal distance only, so cross-road vehicles must be filtered by road in production. Pedestrian crossing is an advisory region, not a moving pedestrian.\n\n'+ '\n'.join(f'- `{name}.rq`: {name.replace("_"," ")}, using actual stored RDF properties.' for name in queries)+'\n\nExample execution:\n```python\nfrom rdflib import Graph\ng = Graph().parse("outputs/demo_kars_delay_seed1/dynamic.ttl")\nprint(list(g.query(open("knowledge_graph/queries/current_lane.rq").read())))\n```\n')

sections=[
('Project title','Delay-Aware Traffic Knowledge Augmented Reachable-Set Planning in SUMO'),
('Abstract','This project implements a simulated IoT traffic pipeline, RDF/SPARQL restrictions, a sampled point-mass reachable graph, graph pruning, corridor candidates, dynamic programming and SLSQP longitudinal smoothing. SUMO executes speed and lane requests. Age-aware occupancy margins and stale-data braking form the primary extension. Comparisons measure executed safety, progress, comfort and timing. This is a project-level approximation inspired by KARS, with no exact paper reproduction claim.'),
('Introduction','Local planning must account for surrounding vehicles and road restrictions as conditions change. Connected observations can support planning, but delayed or missing packets make information less reliable.'),
('Problem statement','Select feasible local motion under road, speed, temporal and vehicle occupancy restrictions while monitoring the age of simulated IoT observations.'),
('Existing system','The referenced KARS work motivates knowledge-augmented reachable-set planning. The project compares ordinary knowledge adjustment, a basic RS traffic-rule ablation and an A* graph search.'),
('Limitations of existing system','The full paper was not supplied, so this project does not assert unverified limitations of its implementation. Our controlled experiment studies sensitivity to delayed and lost observations.'),
('Proposed system','A closed loop converts received traffic packets to RDF, executes SPARQL, prunes reachable motion, scores corridors, runs DP and validates longitudinal smoothing before sending TraCI commands.'),
('Objectives','Create a reproducible laptop simulation, demonstrate traffic-rule changes, maintain useful RDF, compare planners fairly, quantify packet-age effects and expose failures.'),
('Scope','Three-lane straight approach with a signal intersection. IoT simulation, virtual road restrictions, discrete lane planning and independent SUMO safety. No actual sensor, robot vehicle or learned model.'),
('Architecture','See ARCHITECTURE.md for system, data flow, module, algorithm, sequence and deployment diagrams.'),
('Methodology','See METHODOLOGY.md for component mapping, assumptions, extension ranking and implementation provenance.'),
('Algorithms','Offline dynamics samples, online grid-binned graph propagation, swept restriction pruning, terminal-lane corridor extraction, DP, genuine A* and SciPy SLSQP.'),
('Mathematical model','x_next=x+v*dt+0.5*a*dt², v_next=v+a*dt. DP recurrence D(v)=min_u[D(u)+c(u,v)]. Comfort uses RMS of measured acceleration and finite-difference jerk. The lateral state is a lane index, not a continuous steering model.'),
('Implementation','Python modules are in kars/. SUMO XML is under sumo/. RDF ontology and queries are under knowledge_graph/. Commands are in README.md.'),
('Experimental setup','Identical seeded SUMO scenarios, packet loss streams, vehicle dynamics and simulator safety modes. Full experiments use four scenarios, four algorithms and three seeds. Robustness sweeps vary delay and vehicle insertion period.'),
('Results','Use generated outputs/experiments/results.csv and summary.csv. See RESULTS.md for verified run records. Report full-length arrival separately from short integration tests. Never substitute paper metrics.'),
('Comparison','RS ablates traffic rules. A* and DP share traffic constraints and a time-expanded graph. Age-aware KARS uses wider occupancy and stale-data braking. Independent SUMO safety can hide collision differences.'),
('Novelty','The defensible student contribution is implementation and evaluation of packet-age-aware traffic knowledge, with rejection traces and reproducible experiments. KARS itself and age-aware planning in general are not claimed as new inventions.'),
('Advantages','Runs on a laptop, uses auditable SPARQL constraints, separates RS stages and logs measured states and feasible-chain decisions.'),
('Limitations','Incomplete bounded graph, virtual obstacle regions, conservative predictions, advisory crossing, no continuous lateral dynamics, no ground-truth real hardware, limited network and no verified exact paper equations.'),
('Future scope','Paper-exact equation alignment after obtaining PDF, physical obstacle integration, continuous lateral dynamics, future signal timing, validated uncertainty models and optional CARLA co-simulation.'),
('Conclusion','The project demonstrates a reproducible simulated traffic-knowledge planning pipeline. Claims about improvement require the measured comparisons and must account for reduced progress and the SUMO safety layer.'),
('References','Chen et al. (2025), Traffic-Knowledge-Augmented Path Planning for Autonomous Vehicles in Internet of Things, DOI https://doi.org/10.1109/JIOT.2025.3613790. SUMO https://sumo.dlr.de/docs/TraCI.html. RDFLib https://rdflib.readthedocs.io/. SciPy SLSQP https://docs.scipy.org/doc/scipy/reference/optimize.minimize-slsqp.html.')]
(DOC/'REPORT.md').write_text('\n\n'.join('# '+title+'\n\n'+body for title,body in sections)+'\n')

qa=[
('What is your contribution?', 'A reproducible SUMO/RDF/SPARQL planning pipeline with packet-age-aware occupancy expansion and stale-data braking, evaluated against explicit baselines. KARS itself is existing work.'),
('Why SUMO?', 'It supplies lightweight traffic dynamics, signals and a controllable TraCI interface on a laptop.'),
('Why not CARLA?', 'The main objective is traffic knowledge and graph planning. Camera perception and detailed 3D physics would add hardware cost and are outside this scope.'),
('Why a knowledge graph?', 'It provides explicit entities, relationships and queryable restrictions with traceable sources.'),
('Why not only if-else rules?', 'A rule-based implementation could work here. RDF improves separation and extensibility; its computational benefit is not assumed.'),
('Is RS better than A*?', 'They solve different parts here: RS creates a dynamically feasible graph, while A* searches it. The comparison measures search/control behavior and does not prove universal superiority.'),
('What is the actual novelty?', 'The student contribution is the implemented age-aware extension and measured delay/loss evaluation. It is not a claim of globally unprecedented research.'),
('What if communication fails?', 'The channel retains the latest snapshot. The age-aware planner brakes if it is missing or older than the configured timeout.'),
('What if knowledge is outdated?', 'Occupancy bounds expand with age; timeout activates braking. These are conservative engineering assumptions.'),
('Can this work on a real vehicle?', 'The architecture is transferable, but this code lacks continuous vehicle dynamics, sensor validation and safety certification.'),
('Why no real vehicle?', 'Simulation supports repeatable safe experiments within student hardware constraints.'),
('Which dataset is used?', 'Seeded TraCI simulation generates traffic measurements; no external training dataset is used.'),
('What is autonomous driving?', 'Automated sensing, planning and control of a vehicle. This project implements a limited simulated planning/control part.'),
('What is IoT here?', 'Traffic observations transported through a simulated channel with delay and loss.'),
('What is TraCI?', 'SUMO’s client interface for reading simulation state and sending commands.'),
('What is RDF?', 'A graph of subject-predicate-object triples with identifiers and literals.'),
('What is OWL?', 'A vocabulary for defining classes and relationships. This project declares a lightweight schema without a full reasoner.'),
('What is SPARQL?', 'A query language for RDF. The planner actually executes a SELECT query to obtain constraints.'),
('What is an ontology?', 'A structured definition of relevant concepts and properties, such as vehicles, lanes and traffic signals.'),
('What is a reachable set?', 'States attainable under the selected motion model and action bounds within a horizon.'),
('Is your reachable set exact?', 'No. Sampling, grid bins and the state cap make it a finite incomplete approximation.'),
('What is a point-mass model?', 'A simplified longitudinal model with position, velocity and acceleration; no steering dynamics.'),
('Why separate offline and online RS?', 'Offline defines reusable transitions/actions, online anchors propagation to measured ego state, and adjustment imposes current restrictions.'),
('What is a transition matrix?', 'The exported table maps sampled velocities and accelerations to next velocity and displacement; online graph edges represent actual transitions.'),
('What is dt?', 'The planning discretization interval in seconds. Simulation uses a separate smaller interval.'),
('What is the horizon?', 'The number of future planning steps, configured as five by default.'),
('What does spatial restriction mean?', 'A forbidden longitudinal/lane region independent of speed or time.'),
('What does spatial-speed mean?', 'A region with a maximum allowed speed.'),
('What does spatial-temporal mean?', 'A region forbidden during a given active time interval.'),
('What does spatial-temporal-speed mean?', 'A speed restriction that applies inside a region during an active time interval.'),
('Why check swept edges?', 'Checking only endpoints would allow jumping across a narrow obstacle without detecting intersection.'),
('How are solid markings handled?', 'Crossing between lane indices is rejected while the motion segment overlaps the marked interval.'),
('How are pedestrians handled?', 'Only an advisory crossing speed region exists; no moving pedestrian agent is simulated.'),
('How do you detect red lights?', 'TraCI getNextTLS gives the upcoming state and distance. The planner creates a temporary stop-line restriction.'),
('Do you predict future light colors?', 'No. Current red/yellow is conservatively treated as closed for the local horizon.'),
('What is corridor extraction?', 'Full-horizon endpoints are grouped by lane and their reachable ancestors form candidate subgraphs.'),
('Is your corridor continuous?', 'No. It is a sampled graph corridor, not a union of continuous reachable polytopes.'),
('What is spatial margin?', 'Here it is a proxy based on distinct positions per layer. The paper’s exact margin is unverified.'),
('What is a sub-corridor?', 'The DP chain within a candidate graph corridor, chosen by configured costs.'),
('What is dynamic programming?', 'A method that reuses optimal costs to preceding states in a layered graph.'),
('What is the DP recurrence?', 'Best cost to a node equals the minimum parent cost plus that transition’s cost.'),
('Why is the graph acyclic?', 'Every transition increases the time layer, preventing directed cycles.'),
('What is A*?', 'A priority-queue search that ranks accumulated cost plus an admissible future-cost bound.'),
('What heuristic do you use?', '0.01 times the number of remaining layers, since every edge costs at least 0.01.'),
('How is A* validated?', 'Unit tests compare its cost to DP on the same graph.'),
('What is Frenet planning?', 'Planning in longitudinal/lateral coordinates relative to a reference road. A separate Frenet baseline is not implemented.'),
('What is trajectory planning?', 'Producing time-indexed motion targets rather than only a geometric route.'),
('What is SLSQP?', 'SciPy’s sequential least-squares programming optimizer for constrained nonlinear problems.'),
('What does the optimizer minimize?', 'Acceleration squared, acceleration differences and deviation from DP longitudinal positions.'),
('What if optimization fails?', 'The validated feasible DP trajectory is retained.'),
('What is velocity?', 'Rate of position change, measured in meters per second.'),
('What is acceleration?', 'Rate of velocity change, measured in meters per second squared.'),
('What is jerk?', 'Rate of acceleration change, measured in meters per second cubed.'),
('Why measure jerk?', 'Abrupt acceleration changes can indicate reduced ride comfort.'),
('What is RMS?', 'Square root of the mean of squared samples.'),
('How is collision count measured?', 'SUMO collision events involving ego are counted; repeated reporting can count multiple events.'),
('What is success?', 'Ego arrival without a reported collision. Rule compliance is measured separately.'),
('How is clearance measured?', 'Leader bumper gap and distance to active virtual blocks in ego’s lane; it is not full 2D geometric clearance.'),
('What is emergency mode?', 'A no-full-horizon-chain or stale-data condition that requests bounded braking.'),
('How does emergency recover?', 'The next planning cycle can return to normal when a feasible full-horizon chain and fresh knowledge exist.'),
('Does braking guarantee avoidance?', 'No. Late detection and limited deceleration can still leave inadequate stopping distance.'),
('What is stopping distance?', 'For constant braking magnitude b, an idealized estimate is v²/(2b), plus reaction-distance effects.'),
('What is packet loss?', 'A sent simulated observation packet randomly never arrives.'),
('What is packet delay?', 'The time between generating and delivering an observation snapshot.'),
('What is knowledge age?', 'Current simulation time minus the latest received snapshot timestamp.'),
('What is uncertainty growth?', 'A configured distance added to occupancy margin per second of packet age.'),
('Is uncertainty statistically calibrated?', 'No. It is a tunable conservative bound, not a calibrated probability.'),
('Why use random seeds?', 'They make traffic and packet streams repeatable across algorithms.'),
('Why repeat experiments?', 'Traffic and packet randomness can change outcomes; mean and standard deviation show variability.'),
('What is a fair comparison?', 'Same scenario, seed, packet stream, motion limits, cost, smoothing and SUMO safety settings, with documented information differences.'),
('Does RS receive all traffic rules?', 'No. It is explicitly an ablation that keeps physical occupancy but omits traffic-rule pruning.'),
('Does A* use the knowledge graph?', 'No. It receives the same delivered typed constraints directly, isolating graph-query overhead.'),
('Can SUMO hide unsafe planning?', 'Yes. Its independent collision and signal controls remain active. Therefore zero collisions alone are insufficient evidence.'),
('Why retain SUMO safety?', 'It provides a consistent simulator execution layer; its influence is disclosed for every algorithm.'),
('What is static knowledge?', 'Schema and road descriptions that remain stable across cycles.'),
('What is dynamic knowledge?', 'Observed vehicles, signal state and active restrictions refreshed from received packets.'),
('How do updates avoid obsolete triples?', 'The dynamic graph is replaced for each delivered snapshot rather than appending old states indefinitely.'),
('What are literals?', 'Typed RDF values such as speed, timestamp and lane index.'),
('What is a URI?', 'An identifier used to distinguish graph entities and properties.'),
('Do you use graph reasoning?', 'No full OWL reasoner. Planner rules operate on explicit SPARQL result rows.'),
('Why Python?', 'It offers TraCI, RDFLib, scientific optimization, plotting and a readable implementation.'),
('Why NumPy?', 'It supports trajectory arrays and metric calculations.'),
('Why Pandas?', 'It records traffic measurements and aggregates experiment results.'),
('Why SciPy?', 'It supplies the constrained SLSQP optimizer.'),
('Why NetworkX?', 'It represents time-state graphs and supplies graph traversal and topological ordering.'),
('Why Streamlit?', 'It provides a simple local dashboard with simulation controls and saved-result views.'),
('Is this real-time guaranteed?', 'No. Timings are measured; no hard real-time deadline or worst-case execution guarantee exists.'),
('How often does planning run?', 'At the configured planning interval or a changed local road/signal signature.'),
('What is the state cap?', 'A limit on retained states per layer to bound computation, potentially discarding feasible alternatives.'),
('Does finer grid always improve results?', 'It can preserve more detail but costs more computation; the state cap also affects completeness.'),
('How is speed control applied?', 'The first future trajectory velocity becomes a TraCI setSpeed request, constrained by SUMO safety.'),
('How is lane control applied?', 'The first future lane becomes changeLane on non-junction road edges, with safety gaps handled by SUMO.'),
('Are lateral acceleration and jerk measured?', 'No. Exported y is lane center and comfort metrics are longitudinal.'),
('Why are virtual obstacles used?', 'They make traffic-knowledge restrictions explicit and reproducible, but they are not physical collision objects.'),
('What is the static scenario?', 'Road speed, lane marking, crossing advisory and a traffic signal remain present; the name refers to added knowledge events, not a traffic-free road.'),
('What is the semi-dynamic scenario?', 'Construction and a timed temporary lane blockage modify drivable regions.'),
('What is the dynamic scenario?', 'A lead vehicle brakes and later resumes under changing traffic signals.'),
('What is the delay scenario?', 'Dynamic traffic and roadblocks with delayed/lost observation packets.'),
('Is ML implemented?', 'No. The primary extension is analytical age-aware traffic knowledge, avoiding unsupported AI claims.'),
('How would ML be added?', 'Collect labeled conflict examples, split by scenario/seed, validate prediction and then compare a planner using the risk output.'),
('What are the main limitations?', 'No paper-exact verification, finite sampled RS, discrete lateral state, simplified occupancy and signal predictions, virtual restrictions and simulator safety influence.'),
('What should future work prioritize?', 'Obtain the paper PDF for alignment, validate obstacle/signal handling, model lateral dynamics and calibrate uncertainty against ground truth.'),
('How do you defend an extension that reduces speed?', 'Compare clearance, collisions, rule violations and arrival as well as speed. A conservative safety policy has a measurable efficiency cost.'),
('What if no algorithm arrives?', 'Report failure honestly, inspect constraints and horizon/state limits, and avoid presenting a short or blocked run as successful.'),
('How can another student reproduce this?', 'Install requirements, run setup, pytest, scenarios and experiment commands from README, retaining seeds and config.'),
('Where do final numbers come from?', 'Measured ego.csv and traffic.csv, aggregated into metrics.json, results.csv and summary.csv.'),
('Did you reproduce the paper exactly?', 'No. The full PDF was unavailable; the implementation clearly marks project approximations and extensions.')]
assert len(qa)>=100
(DOC/'VIVA.md').write_text('# Viva questions and answers\n\n'+'\n\n'.join(f'{i}. **{q}**\n\n   {a}' for i,(q,a) in enumerate(qa,1))+'\n')

